import bpy,json
print(json.dumps({'file':bpy.data.filepath,'objects':[{'name':o.name,'type':o.type,'loc':list(o.location),'rot':list(o.rotation_euler),'scale':list(o.scale),'dimensions':list(o.dimensions),'bounds':list(map(list,o.bound_box)),'verts':len(o.data.vertices) if o.type=='MESH' else 0,'modifiers':[(m.name,m.type) for m in o.modifiers],'keys':list(o.data.shape_keys.key_blocks.keys()) if o.type=='MESH' and o.data.shape_keys else [],'animation':bool(o.animation_data),'materials':[m.name for m in o.data.materials] if o.type=='MESH' else []} for o in bpy.context.scene.objects]},indent=2))
